    if (x >= 10) return DARK_OAK;                                                   // landing
    if (z >= 17) return STONE;                                                      // bathroom
    return SPRUCE;                                                                  // front bedroom
  }
  if (y === 13) return BIRCH;                                                       // top room and box room
  if (y === 17) return GRAVEL;                                                      // roof deck
  return null;
}

