  // focal piece: a flower pot on the table, directly under the lantern
  g.set(4, 7, 6, "flower_pot");

  // light: two hanging lanterns from the ceiling, one over the table and one over the seat's east end
  g.set(4, 8, 6, ...B.lantern(true));
